def main():
    base = json.load(open(os.path.join(HERE, 'base.json')))
    out = {}
    for code, (a3, num, tel, names) in base.items():
        weak = []
        cur = list(names)
        for n in EXTRA.get(code, []):
            (weak if n.startswith('~') else cur).append(n.lstrip('~'))
        cur = [n for i, n in enumerate(cur) if n not in weak and n not in cur[:i]]
        show = [names[0]] + [n for n in names[1:4] if ',' not in n and len(n) < 28][:1]
        out[code] = {'a3': a3, 'num': num, 'tel': tel, 'show': show, 'names': cur, 'weak': weak, 'auto': []}
    for lang in LANGS:
        try:
            tr = gettext.translation('iso3166-1', pycountry.LOCALES_DIR, languages=[lang])
        except FileNotFoundError:
            print('no locale', lang); continue
        for c in pycountry.countries:
            if c.alpha_2 not in out: continue
            for attr in ('name', 'official_name', 'common_name'):
                src = getattr(c, attr, None)
                if not src: continue
                t = tr.gettext(src)
                if t and t != src and t not in out[c.alpha_2]['auto']:
                    out[c.alpha_2]['auto'].append(t)
    json.dump(out, open(os.path.join(HERE, 'raw.json'), 'w'), ensure_ascii=False)
    print('curated', sum(len(v['names']) + len(v['weak']) for v in out.values()), 'auto', sum(len(v['auto']) for v in out.values()))

main()
